import { TriviaQuestion } from '../trivia-types'

export const MOVIES_TV_QUESTIONS: TriviaQuestion[] = [
  { id: 'mov-1', category: 'movies-tv', difficulty: 'easy', question: 'What 1994 film follows a man sitting on a bench telling strangers the story of his life?', answer: 'Forrest Gump', options: ['Forrest Gump', 'The Shawshank Redemption', 'Pulp Fiction', 'Cast Away'], explanation: 'Forrest Gump, starring Tom Hanks, won six Academy Awards including Best Picture. The famous bench scenes were filmed in Savannah, Georgia.' },
  { id: 'mov-2', category: 'movies-tv', difficulty: 'easy', question: 'In The Wizard of Oz, what color are Dorothy\'s famous slippers?', answer: 'Ruby red', options: ['Silver', 'Ruby red', 'Gold', 'Glass'], explanation: 'Dorothy\'s ruby slippers are one of the most iconic props in film history. In L. Frank Baum\'s original novel, the slippers were actually silver.' },
  { id: 'mov-3', category: 'movies-tv', difficulty: 'easy', question: 'Which film features the quote "Here\'s looking at you, kid"?', answer: 'Casablanca', options: ['Gone with the Wind', 'Casablanca', 'Citizen Kane', 'The Maltese Falcon'], explanation: 'Humphrey Bogart says this line to Ingrid Bergman in the 1942 classic Casablanca. The American Film Institute ranked it the 5th greatest movie quote of all time.' },
  { id: 'mov-4', category: 'movies-tv', difficulty: 'easy', question: 'What is the highest-grossing film of all time worldwide (not adjusted for inflation)?', answer: 'Avatar', options: ['Avengers: Endgame', 'Avatar', 'Titanic', 'Star Wars: The Force Awakens'], explanation: 'James Cameron\'s Avatar (2009) has earned over $2.9 billion worldwide. Cameron also directed Titanic, which was the highest-grossing film for over a decade before Avatar surpassed it. Avengers: Endgame held the record briefly before Avatar\'s 2021 re-release reclaimed it.' },
  { id: 'mov-5', category: 'movies-tv', difficulty: 'easy', question: 'Who directed Jaws, E.T., and Schindler\'s List?', answer: 'Steven Spielberg', options: ['Martin Scorsese', 'Steven Spielberg', 'Francis Ford Coppola', 'George Lucas'], explanation: 'Steven Spielberg is one of the most commercially successful directors in history. Jaws (1975) is often credited as the first summer blockbuster.' },
  { id: 'mov-6', category: 'movies-tv', difficulty: 'easy', question: 'In the Star Wars franchise, what is the name of Han Solo\'s ship?', answer: 'Millennium Falcon', options: ['X-Wing', 'Millennium Falcon', 'Star Destroyer', 'TIE Fighter'], explanation: 'The Millennium Falcon is described as making the Kessel Run in less than twelve parsecs. Han Solo won it from Lando Calrissian in a game of sabacc.' },
  { id: 'mov-7', category: 'movies-tv', difficulty: 'easy', question: 'What was the first feature-length animated Disney film?', answer: 'Snow White and the Seven Dwarfs', options: ['Pinocchio', 'Fantasia', 'Snow White and the Seven Dwarfs', 'Bambi'], explanation: 'Snow White and the Seven Dwarfs was released in 1937 and was a massive financial success. Critics had dubbed it "Disney\'s Folly" during production, predicting it would bankrupt the studio.' },
  { id: 'mov-8', category: 'movies-tv', difficulty: 'easy', question: 'What TV show features characters named Ross, Rachel, Monica, Chandler, Joey, and Phoebe?', answer: 'Friends', options: ['Seinfeld', 'Friends', 'How I Met Your Mother', 'The Big Bang Theory'], explanation: 'Friends ran for 10 seasons on NBC from 1994 to 2004. The cast famously negotiated as a group, eventually earning $1 million per episode each in the final seasons.' },
  { id: 'mov-9', category: 'movies-tv', difficulty: 'easy', question: 'Who plays Jack Dawson in the 1997 film Titanic?', answer: 'Leonardo DiCaprio', options: ['Brad Pitt', 'Leonardo DiCaprio', 'Matt Damon', 'Johnny Depp'], explanation: 'Titanic was directed by James Cameron and won 11 Academy Awards, tying Ben-Hur\'s record. DiCaprio did not receive an Oscar nomination for the role.' },
  { id: 'mov-10', category: 'movies-tv', difficulty: 'easy', question: 'In what movie does a character say "I see dead people"?', answer: 'The Sixth Sense', options: ['The Sixth Sense', 'Ghost', 'The Others', 'Poltergeist'], explanation: 'Haley Joel Osment delivers this iconic line in M. Night Shyamalan\'s 1999 thriller. The film\'s twist ending became one of the most discussed in cinema history.' },
  { id: 'mov-11', category: 'movies-tv', difficulty: 'easy', question: 'What fictional country is Black Panther from?', answer: 'Wakanda', options: ['Zamunda', 'Wakanda', 'Latveria', 'Genosha'], explanation: 'Wakanda is a technologically advanced African nation powered by vibranium. Black Panther (2018) was the first superhero film nominated for Best Picture at the Oscars.' },
  { id: 'mov-12', category: 'movies-tv', difficulty: 'easy', question: 'Which actor plays the character of Michael Scott in the US version of The Office?', answer: 'Steve Carell', options: ['Steve Carell', 'Will Ferrell', 'Rainn Wilson', 'John Krasinski'], explanation: 'Steve Carell played Michael Scott for seasons 1 through 7 of the show. The UK original starred Ricky Gervais as David Brent.' },
  { id: 'mov-13', category: 'movies-tv', difficulty: 'easy', question: 'What 1972 film, directed by Francis Ford Coppola, follows the Corleone crime family?', answer: 'The Godfather', options: ['Goodfellas', 'Scarface', 'The Godfather', 'Casino'], explanation: 'The Godfather won three Academy Awards including Best Picture and Best Actor for Marlon Brando. Brando famously refused his Oscar, sending Sacheen Littlefeather to decline it.' },
  { id: 'mov-14', category: 'movies-tv', difficulty: 'easy', question: 'In Finding Nemo, what type of fish is Nemo?', answer: 'Clownfish', options: ['Blue tang', 'Clownfish', 'Goldfish', 'Angelfish'], explanation: 'Nemo is an ocellaris clownfish (also called a false percula clownfish). After the film\'s release, demand for clownfish as pets surged significantly.' },
  { id: 'mov-15', category: 'movies-tv', difficulty: 'easy', question: 'What is the name of the fictional high school in Grease?', answer: 'Rydell High', options: ['Bayside High', 'Rydell High', 'West Beverly Hills High', 'Shermer High'], explanation: 'Rydell High was named after Bobby Rydell, a 1960s teen idol. The 1978 film starred John Travolta and Olivia Newton-John, both of whom were notably older than typical high schoolers.' },
  { id: 'mov-16', category: 'movies-tv', difficulty: 'easy', question: 'Which Pixar film features a rat who dreams of becoming a chef in Paris?', answer: 'Ratatouille', options: ['Ratatouille', 'Up', 'Inside Out', 'Coco'], explanation: 'Ratatouille was released in 2007 and won the Academy Award for Best Animated Feature. The rat protagonist is named Remy, and the dish ratatouille he prepares in the film is a real Provencal vegetable stew.' },
  { id: 'mov-17', category: 'movies-tv', difficulty: 'easy', question: 'In what TV show does a high school chemistry teacher turn to making methamphetamine?', answer: 'Breaking Bad', options: ['Ozark', 'Breaking Bad', 'Weeds', 'The Wire'], explanation: 'Breaking Bad starred Bryan Cranston as Walter White and ran for five seasons on AMC (2008-2013). Cranston won four Emmy Awards for Outstanding Lead Actor for the role.' },
  { id: 'mov-18', category: 'movies-tv', difficulty: 'easy', question: 'Who directed the Lord of the Rings trilogy?', answer: 'Peter Jackson', options: ['Peter Jackson', 'Ridley Scott', 'James Cameron', 'Christopher Nolan'], explanation: 'Peter Jackson filmed all three Lord of the Rings movies simultaneously in New Zealand. The Return of the King won all 11 Academy Awards it was nominated for, tying the all-time record.' },
  { id: 'mov-19', category: 'movies-tv', difficulty: 'easy', question: 'What is the name of the talking snowman in Frozen?', answer: 'Olaf', options: ['Sven', 'Olaf', 'Kristoff', 'Hans'], explanation: 'Olaf is voiced by Josh Gad and dreams of experiencing summer. Frozen (2013) became the highest-grossing animated film at the time of its release.' },
  { id: 'mov-20', category: 'movies-tv', difficulty: 'easy', question: 'Which movie features the quote "May the Force be with you"?', answer: 'Star Wars', options: ['Star Trek', 'Star Wars', 'Battlestar Galactica', 'The Fifth Element'], explanation: 'This line appears throughout the Star Wars franchise, first spoken by General Dodonna in the original 1977 film. It was ranked #8 on the AFI\'s list of greatest movie quotes.' },
  { id: 'mov-21', category: 'movies-tv', difficulty: 'easy', question: 'What animated film features a clownfish father searching for his lost son across the ocean?', answer: 'Finding Nemo', options: ['Finding Nemo', 'Shark Tale', 'The Little Mermaid', 'Moana'], explanation: 'Finding Nemo (2003) won the Academy Award for Best Animated Feature. It was the first Pixar film to win this award, which was only established in 2001.' },
  { id: 'mov-22', category: 'movies-tv', difficulty: 'easy', question: 'In the Harry Potter films, what position does Harry play on his Quidditch team?', answer: 'Seeker', options: ['Chaser', 'Beater', 'Keeper', 'Seeker'], explanation: 'The Seeker\'s job is to catch the Golden Snitch, which is worth 150 points and ends the game. Harry becomes the youngest Seeker in a century at Hogwarts.' },
  { id: 'mov-23', category: 'movies-tv', difficulty: 'easy', question: 'What 1993 Steven Spielberg film brought dinosaurs to life using groundbreaking CGI?', answer: 'Jurassic Park', options: ['Jurassic Park', 'The Lost World', 'King Kong', 'Godzilla'], explanation: 'Jurassic Park was based on Michael Crichton\'s novel and grossed over $900 million worldwide. The film used a combination of CGI and Stan Winston\'s animatronic dinosaurs.' },
  { id: 'mov-24', category: 'movies-tv', difficulty: 'easy', question: 'What is the name of Batman\'s butler?', answer: 'Alfred', options: ['Jarvis', 'Alfred', 'Watson', 'Jeeves'], explanation: 'Alfred Pennyworth has been Batman\'s loyal butler and father figure since the character\'s introduction in 1943. Michael Caine memorably played Alfred in Christopher Nolan\'s Dark Knight trilogy.' },
  { id: 'mov-25', category: 'movies-tv', difficulty: 'easy', question: 'Which TV series follows the Stark family in a fantasy world of warring kingdoms?', answer: 'Game of Thrones', options: ['The Witcher', 'Game of Thrones', 'Lord of the Rings: The Rings of Power', 'Vikings'], explanation: 'Game of Thrones aired on HBO from 2011 to 2019 and was based on George R.R. Martin\'s A Song of Ice and Fire novels. It became one of the most-watched series in television history.' },
  { id: 'mov-26', category: 'movies-tv', difficulty: 'easy', question: 'Who played the Joker in The Dark Knight (2008)?', answer: 'Heath Ledger', options: ['Jack Nicholson', 'Joaquin Phoenix', 'Heath Ledger', 'Jared Leto'], explanation: 'Heath Ledger won a posthumous Academy Award for Best Supporting Actor for the role. He passed away in January 2008, months before the film\'s release.' },
  { id: 'mov-27', category: 'movies-tv', difficulty: 'easy', question: 'What Seinfeld catchphrase involves a soup vendor refusing service?', answer: 'No soup for you!', options: ['No soup for you!', 'Yada yada yada', 'Not that there\'s anything wrong with that', 'Serenity now!'], explanation: 'The Soup Nazi episode aired in 1995 and became one of the most iconic Seinfeld episodes. The character was inspired by a real New York City soup vendor named Al Yeganeh.' },
  { id: 'mov-28', category: 'movies-tv', difficulty: 'easy', question: 'In The Lion King, what is Simba\'s father\'s name?', answer: 'Mufasa', options: ['Scar', 'Mufasa', 'Rafiki', 'Zazu'], explanation: 'Mufasa was voiced by James Earl Jones in both the 1994 original and the 2019 remake. His death scene is considered one of the most emotional moments in animated film history.' },
  { id: 'mov-29', category: 'movies-tv', difficulty: 'easy', question: 'What is the name of the fictional paper company in The Office (US)?', answer: 'Dunder Mifflin', options: ['Wernham Hogg', 'Dunder Mifflin', 'Prestige Worldwide', 'Vandelay Industries'], explanation: 'Dunder Mifflin is based in Scranton, Pennsylvania. Wernham Hogg is the equivalent company in the UK version of The Office.' },
  { id: 'mov-30', category: 'movies-tv', difficulty: 'easy', question: 'Who voices Woody in the Toy Story franchise?', answer: 'Tom Hanks', options: ['Tim Allen', 'Tom Hanks', 'Billy Crystal', 'Robin Williams'], explanation: 'Tom Hanks has voiced Woody in all four Toy Story films (1995-2019). Tim Allen voices Buzz Lightyear in the same franchise.' },
  { id: 'mov-31', category: 'movies-tv', difficulty: 'easy', question: 'What superhero film was the first to gross over $1 billion at the worldwide box office?', answer: 'The Dark Knight', options: ['Spider-Man', 'The Avengers', 'The Dark Knight', 'Iron Man'], explanation: 'The Dark Knight (2008) earned over $1 billion globally, making it the first superhero film to reach that milestone. It was only the fourth film ever to cross $1 billion at the time.' },
  { id: 'mov-32', category: 'movies-tv', difficulty: 'easy', question: 'In what TV show is the catchphrase "How you doin\'?" frequently used?', answer: 'Friends', options: ['Seinfeld', 'Friends', 'The Fresh Prince of Bel-Air', 'Happy Days'], explanation: 'Joey Tribbiani, played by Matt LeBlanc, uses "How you doin\'?" as his signature pickup line. The character later got his own spinoff series called Joey, which lasted two seasons.' },
  { id: 'mov-33', category: 'movies-tv', difficulty: 'easy', question: 'What 1939 film features the line "Frankly, my dear, I don\'t give a damn"?', answer: 'Gone with the Wind', options: ['Casablanca', 'Gone with the Wind', 'The Wizard of Oz', 'Mr. Smith Goes to Washington'], explanation: 'Clark Gable delivers this line as Rhett Butler in Gone with the Wind. The AFI ranked it the #1 greatest movie quote of all time.' },
  { id: 'mov-34', category: 'movies-tv', difficulty: 'easy', question: 'What is the name of the hobbit played by Elijah Wood in The Lord of the Rings?', answer: 'Frodo Baggins', options: ['Bilbo Baggins', 'Samwise Gamgee', 'Frodo Baggins', 'Peregrin Took'], explanation: 'Frodo Baggins carries the One Ring to Mount Doom to destroy it. Elijah Wood was only 18 when he was cast in the role.' },
  { id: 'mov-35', category: 'movies-tv', difficulty: 'medium', question: 'What was the first Pixar film to receive a PG rating?', answer: 'The Incredibles', options: ['Finding Nemo', 'The Incredibles', 'Up', 'Brave'], explanation: 'The Incredibles (2004) was Pixar\'s first PG-rated film due to its action sequences. All previous Pixar films had been rated G.' },
  { id: 'mov-36', category: 'movies-tv', difficulty: 'medium', question: 'Which Alfred Hitchcock film features the iconic shower scene?', answer: 'Psycho', options: ['Vertigo', 'Psycho', 'Rear Window', 'The Birds'], explanation: 'The shower scene in Psycho (1960) contains about 70 camera angles in 45 seconds. Hitchcock used chocolate syrup for the blood since the film was shot in black and white.' },
  { id: 'mov-37', category: 'movies-tv', difficulty: 'medium', question: 'In Quentin Tarantino\'s Pulp Fiction, what does Marcellus Wallace\'s briefcase supposedly contain?', answer: 'It is never revealed', options: ['Gold bars', 'Diamonds', 'Marcellus Wallace\'s soul', 'It is never revealed'], explanation: 'The glowing contents of the briefcase are one of cinema\'s great mysteries. Tarantino has stated the briefcase originally contained diamonds but he changed it to be ambiguous.' },
  { id: 'mov-38', category: 'movies-tv', difficulty: 'medium', question: 'What film won the first-ever Academy Award for Best Picture?', answer: 'Wings', options: ['Sunrise', 'Wings', 'The Jazz Singer', 'Metropolis'], explanation: 'Wings (1927) won Best Picture at the 1st Academy Awards ceremony held in 1929. It is a silent film about World War I fighter pilots and remains the only fully silent film to win Best Picture.' },
  { id: 'mov-39', category: 'movies-tv', difficulty: 'medium', question: 'Who is the only person to have won Academy Awards for both Best Director and Best Actor?', answer: 'No one has achieved this', options: ['Clint Eastwood', 'Kevin Costner', 'No one has achieved this', 'Mel Gibson'], explanation: 'No individual has won both Best Director and Best Actor Oscars. Several have been nominated in both categories, but none have won both.' },
  { id: 'mov-40', category: 'movies-tv', difficulty: 'medium', question: 'What Stanley Kubrick film features the line "Here\'s Johnny!" as a character breaks through a door with an axe?', answer: 'The Shining', options: ['A Clockwork Orange', 'The Shining', 'Full Metal Jacket', 'Eyes Wide Shut'], explanation: 'Jack Nicholson ad-libbed the "Here\'s Johnny!" line, referencing Ed McMahon\'s introduction of Johnny Carson. Kubrick reportedly required 60+ takes for some scenes in the film.' },
  { id: 'mov-41', category: 'movies-tv', difficulty: 'medium', question: 'Which Marvel Cinematic Universe film introduced the character of Black Panther?', answer: 'Captain America: Civil War', options: ['Avengers: Age of Ultron', 'Captain America: Civil War', 'Black Panther', 'The Avengers'], explanation: 'Chadwick Boseman first appeared as T\'Challa/Black Panther in Captain America: Civil War (2016). His standalone film was released two years later in 2018.' },
  { id: 'mov-42', category: 'movies-tv', difficulty: 'medium', question: 'What is the name of the computer system that becomes self-aware in 2001: A Space Odyssey?', answer: 'HAL 9000', options: ['WOPR', 'Skynet', 'HAL 9000', 'ARIA'], explanation: 'HAL 9000\'s iconic red eye and calm voice make it one of film\'s greatest villains. A popular myth claims HAL is a one-letter shift from IBM, but director Kubrick and writer Arthur C. Clarke denied this.' },
  { id: 'mov-43', category: 'movies-tv', difficulty: 'medium', question: 'In The Sopranos, what is Tony Soprano\'s legitimate business front?', answer: 'Waste management', options: ['Construction company', 'Waste management', 'Restaurant chain', 'Auto dealership'], explanation: 'Tony Soprano, played by James Gandolfini, claims to be in "waste management" when asked about his profession. The Sopranos is widely considered the show that launched the golden age of prestige television.' },
  { id: 'mov-44', category: 'movies-tv', difficulty: 'medium', question: 'What 1999 film popularized the concept of simulated reality with its "red pill, blue pill" scene?', answer: 'The Matrix', options: ['The Truman Show', 'Dark City', 'The Matrix', 'eXistenZ'], explanation: 'The Matrix starred Keanu Reeves as Neo and was directed by the Wachowskis. Its "bullet time" camera effect revolutionized visual effects in cinema.' },
  { id: 'mov-45', category: 'movies-tv', difficulty: 'medium', question: 'Which James Bond actor has appeared in the most Bond films?', answer: 'Roger Moore', options: ['Sean Connery', 'Roger Moore', 'Daniel Craig', 'Pierce Brosnan'], explanation: 'Roger Moore appeared in seven Bond films from 1973 to 1985. Sean Connery appeared in six official Bond films (seven if you count Never Say Never Again, which was not an official Eon production).' },
  { id: 'mov-46', category: 'movies-tv', difficulty: 'medium', question: 'What TV show features a family of "bluth" that has lost their fortune?', answer: 'Arrested Development', options: ['Schitt\'s Creek', 'Arrested Development', 'Succession', 'The Royal Tenenbaums'], explanation: 'Arrested Development premiered on Fox in 2003, starring Jason Bateman as Michael Bluth. Despite critical acclaim and a cult following, it was canceled after three seasons before being revived by Netflix.' },
  { id: 'mov-47', category: 'movies-tv', difficulty: 'medium', question: 'What was the first film to use CGI for a main character?', answer: 'Young Sherlock Holmes', options: ['Tron', 'Young Sherlock Holmes', 'The Abyss', 'Terminator 2'], explanation: 'Young Sherlock Holmes (1985) featured the first fully CGI character: a stained-glass knight. The effect was created by Lucasfilm\'s computer graphics division, which later became Pixar.' },
  { id: 'mov-48', category: 'movies-tv', difficulty: 'medium', question: 'In Christopher Nolan\'s Inception, what object does Cobb use as his totem?', answer: 'A spinning top', options: ['A loaded die', 'A spinning top', 'A chess piece', 'A poker chip'], explanation: 'The spinning top originally belonged to Cobb\'s wife Mal. If the top keeps spinning, Cobb is still in a dream; if it falls, he is in reality. The film\'s ambiguous ending became a major point of debate.' },
  { id: 'mov-49', category: 'movies-tv', difficulty: 'medium', question: 'Which film holds the record for most Academy Award wins?', answer: 'The Lord of the Rings: The Return of the King', options: ['Ben-Hur', 'Titanic', 'The Lord of the Rings: The Return of the King', 'West Side Story'], explanation: 'The Return of the King won all 11 Oscars it was nominated for at the 2004 ceremony. It shares the record of 11 wins with Ben-Hur (1959) and Titanic (1997).' },
  { id: 'mov-50', category: 'movies-tv', difficulty: 'medium', question: 'What was the name of the coffee shop where the Friends characters regularly gathered?', answer: 'Central Perk', options: ['Central Perk', 'The Beanery', 'Java Jive', 'Cup O\' Joe'], explanation: 'Central Perk was located in Greenwich Village, Manhattan. The orange couch became an iconic piece of TV set design and was recreated for the 2021 Friends reunion special.' },
  { id: 'mov-51', category: 'movies-tv', difficulty: 'medium', question: 'Who directed the 1994 film The Shawshank Redemption?', answer: 'Frank Darabont', options: ['Frank Darabont', 'Martin Scorsese', 'David Fincher', 'Rob Reiner'], explanation: 'Frank Darabont adapted the screenplay from Stephen King\'s novella Rita Hayworth and Shawshank Redemption. Despite being a box office disappointment, it became the #1 rated film on IMDb.' },
  { id: 'mov-52', category: 'movies-tv', difficulty: 'medium', question: 'In what year was the first Star Wars film released?', answer: '1977', options: ['1975', '1977', '1979', '1980'], explanation: 'Star Wars (later subtitled A New Hope) was released on May 25, 1977. Nearly every studio passed on the project, and Fox executives expected it to be a flop.' },
  { id: 'mov-53', category: 'movies-tv', difficulty: 'medium', question: 'Which Martin Scorsese film features Robert De Niro as a taxi driver plotting an assassination?', answer: 'Taxi Driver', options: ['Taxi Driver', 'Goodfellas', 'Raging Bull', 'Mean Streets'], explanation: 'Taxi Driver (1976) is famous for De Niro\'s "You talkin\' to me?" scene, which was largely improvised. The script was written by Paul Schrader.' },
  { id: 'mov-54', category: 'movies-tv', difficulty: 'medium', question: 'What actress has won the most Academy Awards for acting?', answer: 'Katharine Hepburn', options: ['Meryl Streep', 'Katharine Hepburn', 'Frances McDormand', 'Ingrid Bergman'], explanation: 'Katharine Hepburn won four Best Actress Oscars over her career (1934, 1968, 1969, 1982). Notably, she never attended any of the ceremonies to accept her awards.' },
  { id: 'mov-55', category: 'movies-tv', difficulty: 'medium', question: 'In Breaking Bad, what is Walter White\'s street alias?', answer: 'Heisenberg', options: ['The Cook', 'Heisenberg', 'Cap\'n Cook', 'The Chemist'], explanation: 'Walter White chose the name Heisenberg after Werner Heisenberg, the physicist known for the uncertainty principle. The name symbolizes the unpredictable nature of Walt\'s transformation.' },
  { id: 'mov-56', category: 'movies-tv', difficulty: 'medium', question: 'What was the first feature film directed by Quentin Tarantino?', answer: 'Reservoir Dogs', options: ['Pulp Fiction', 'Reservoir Dogs', 'True Romance', 'Kill Bill: Volume 1'], explanation: 'Reservoir Dogs was released in 1992 and established Tarantino\'s signature style of nonlinear storytelling and sharp dialogue. It was made on a budget of just $1.2 million.' },
  { id: 'mov-57', category: 'movies-tv', difficulty: 'medium', question: 'Which TV show coined the phrase "Winter is coming"?', answer: 'Game of Thrones', options: ['Vikings', 'Game of Thrones', 'The Last Kingdom', 'Outlander'], explanation: '"Winter is coming" is the motto of House Stark. In the show\'s world, seasons can last for years, and a long winter brings the threat of the White Walkers.' },
  { id: 'mov-58', category: 'movies-tv', difficulty: 'medium', question: 'In The Office (US), what is Dwight Schrute\'s family farm primarily known for growing?', answer: 'Beets', options: ['Corn', 'Beets', 'Potatoes', 'Wheat'], explanation: 'Schrute Farms grows beets and also operates as a bed and breakfast. Dwight proudly describes it as a 60-acre working beet farm that has been in his family for generations.' },
  { id: 'mov-59', category: 'movies-tv', difficulty: 'medium', question: 'What is Rosebud in the film Citizen Kane?', answer: 'A sled', options: ['A childhood nickname', 'A sled', 'A pet dog', 'A music box'], explanation: 'Rosebud is the name of Charles Foster Kane\'s childhood sled, representing the innocence he lost. Citizen Kane (1941) is frequently cited as the greatest film ever made by critics and filmmakers.' },
  { id: 'mov-60', category: 'movies-tv', difficulty: 'medium', question: 'Which actor has played James Bond the most recently in an official Eon Productions film?', answer: 'Daniel Craig', options: ['Pierce Brosnan', 'Daniel Craig', 'Timothy Dalton', 'Roger Moore'], explanation: 'Daniel Craig played Bond in five films from Casino Royale (2006) to No Time to Die (2021). He brought a grittier, more physical interpretation to the role.' },
  { id: 'mov-61', category: 'movies-tv', difficulty: 'medium', question: 'What is the fictional chemical compound Walter White produces in Breaking Bad?', answer: 'Methamphetamine', options: ['Methamphetamine', 'Cocaine', 'LSD', 'Fentanyl'], explanation: 'Walter White\'s "Blue Sky" methamphetamine is noted for its distinctive blue color and exceptional purity. In reality, methamphetamine\'s color depends on impurities in the synthesis process.' },
  { id: 'mov-62', category: 'movies-tv', difficulty: 'medium', question: 'In the Harry Potter films, who kills Dumbledore?', answer: 'Severus Snape', options: ['Voldemort', 'Draco Malfoy', 'Severus Snape', 'Bellatrix Lestrange'], explanation: 'Snape kills Dumbledore at the end of Harry Potter and the Half-Blood Prince, but it is later revealed that Dumbledore had asked Snape to do it. This twist was one of the series\' most shocking moments.' },
  { id: 'mov-63', category: 'movies-tv', difficulty: 'medium', question: 'What was the first James Bond film?', answer: 'Dr. No', options: ['Goldfinger', 'Dr. No', 'From Russia with Love', 'Thunderball'], explanation: 'Dr. No was released in 1962, starring Sean Connery as Bond. The film was made on a budget of about $1 million and launched one of the most successful franchises in cinema history.' },
  { id: 'mov-64', category: 'movies-tv', difficulty: 'medium', question: 'What Hitchcock film features James Stewart as a photographer who believes he witnesses a murder from his apartment window?', answer: 'Rear Window', options: ['Vertigo', 'Rear Window', 'Rope', 'Dial M for Murder'], explanation: 'Rear Window (1954) starred James Stewart and Grace Kelly and is set almost entirely in one apartment. The entire courtyard set was built on a Paramount Studios soundstage.' },
  { id: 'mov-65', category: 'movies-tv', difficulty: 'medium', question: 'Which Coen Brothers film won the Academy Award for Best Picture in 2008?', answer: 'No Country for Old Men', options: ['Fargo', 'No Country for Old Men', 'True Grit', 'The Big Lebowski'], explanation: 'No Country for Old Men won four Oscars including Best Picture and Best Director. Javier Bardem\'s portrayal of Anton Chigurh is considered one of the greatest villain performances in cinema.' },
  { id: 'mov-66', category: 'movies-tv', difficulty: 'medium', question: 'What is the longest-running primetime animated TV series in the United States?', answer: 'The Simpsons', options: ['Family Guy', 'South Park', 'The Simpsons', 'King of the Hill'], explanation: 'The Simpsons premiered on December 17, 1989, and has aired over 750 episodes. It began as short segments on The Tracey Ullman Show before getting its own series.' },
  { id: 'mov-67', category: 'movies-tv', difficulty: 'medium', question: 'In Silence of the Lambs, what is Hannibal Lecter\'s profession?', answer: 'Psychiatrist', options: ['Surgeon', 'Psychiatrist', 'Professor', 'Forensic pathologist'], explanation: 'Dr. Hannibal Lecter is a brilliant psychiatrist turned serial killer and cannibal. Anthony Hopkins won the Oscar for Best Actor despite having only about 16 minutes of screen time.' },
  { id: 'mov-68', category: 'movies-tv', difficulty: 'medium', question: 'What streaming service produced the show Stranger Things?', answer: 'Netflix', options: ['Hulu', 'Netflix', 'Amazon Prime', 'HBO Max'], explanation: 'Stranger Things debuted on Netflix in 2016 and became a massive cultural phenomenon. The Duffer Brothers created the show as a love letter to 1980s pop culture, especially the works of Spielberg and Stephen King.' },
  { id: 'mov-69', category: 'movies-tv', difficulty: 'medium', question: 'In the MCU, what are the six Infinity Stones?', answer: 'Space, Mind, Reality, Power, Time, Soul', options: ['Space, Mind, Reality, Power, Time, Soul', 'Space, Mind, Reality, Power, Life, Death', 'Space, Mind, Truth, Power, Time, Soul', 'Space, Mind, Reality, Force, Time, Soul'], explanation: 'Each Infinity Stone controls an essential aspect of existence. When combined in the Infinity Gauntlet, they grant the user virtually unlimited power, as seen in Avengers: Infinity War.' },
  { id: 'mov-70', category: 'movies-tv', difficulty: 'medium', question: 'What film popularized the "Wilhelm scream" sound effect that has been used in hundreds of movies?', answer: 'The Charge at Feather River', options: ['Star Wars', 'The Charge at Feather River', 'Indiana Jones', 'Distant Drums'], explanation: 'While first recorded for Distant Drums (1951), the scream got its name from Private Wilhelm in The Charge at Feather River (1953). Sound designer Ben Burtt popularized its reuse in Star Wars and Indiana Jones.' },
  { id: 'mov-71', category: 'movies-tv', difficulty: 'medium', question: 'Which TV show features a teacher named Mr. Feeney?', answer: 'Boy Meets World', options: ['Saved by the Bell', 'Boy Meets World', 'Malcolm in the Middle', 'The Wonder Years'], explanation: 'George Feeney, played by William Daniels, was a teacher and mentor across all seven seasons of Boy Meets World (1993-2000). Daniels also returned for the spinoff series Girl Meets World.' },
  { id: 'mov-72', category: 'movies-tv', difficulty: 'medium', question: 'What Christopher Nolan film tells its story in reverse chronological order?', answer: 'Memento', options: ['Memento', 'Tenet', 'The Prestige', 'Inception'], explanation: 'Memento (2000) follows a man with short-term memory loss investigating his wife\'s murder. The reverse structure lets the audience experience the protagonist\'s confusion firsthand.' },
  { id: 'mov-73', category: 'movies-tv', difficulty: 'medium', question: 'What is the name of Tony Stark\'s AI assistant in the Iron Man films?', answer: 'J.A.R.V.I.S.', options: ['F.R.I.D.A.Y.', 'J.A.R.V.I.S.', 'E.D.I.T.H.', 'K.A.R.E.N.'], explanation: 'J.A.R.V.I.S. stands for Just A Rather Very Intelligent System, voiced by Paul Bettany. After J.A.R.V.I.S. becomes the Vision, Tony replaces it with F.R.I.D.A.Y.' },
  { id: 'mov-74', category: 'movies-tv', difficulty: 'medium', question: 'Which animated Disney film was the first to be set in Africa?', answer: 'The Lion King', options: ['Tarzan', 'The Lion King', 'Madagascar', 'The Prince of Egypt'], explanation: 'The Lion King (1994) is set in the Pride Lands of Africa and was Disney\'s first animated film with an original story not based on existing source material (though it draws parallels to Hamlet).' },
  { id: 'mov-75', category: 'movies-tv', difficulty: 'medium', question: 'In Seinfeld, what is George Costanza\'s famous fake charity?', answer: 'The Human Fund', options: ['The George Fund', 'The Human Fund', 'People for People', 'Costanza Foundation'], explanation: 'The Human Fund\'s motto is "Money for People." George creates it to avoid buying Christmas gifts for coworkers, instead giving them donation cards in their names.' },
  { id: 'mov-76', category: 'movies-tv', difficulty: 'medium', question: 'Who composed the iconic theme music for the film Jaws?', answer: 'John Williams', options: ['Hans Zimmer', 'John Williams', 'Jerry Goldsmith', 'Ennio Morricone'], explanation: 'John Williams\' two-note shark motif became one of the most recognizable themes in film history. Williams has composed scores for Star Wars, Indiana Jones, Harry Potter, and many other blockbusters.' },
  { id: 'mov-77', category: 'movies-tv', difficulty: 'medium', question: 'What TV show popularized the "mockumentary" format and debuted in the UK in 2001?', answer: 'The Office', options: ['Parks and Recreation', 'The Office', 'Modern Family', 'Arrested Development'], explanation: 'The Office UK was created by Ricky Gervais and Stephen Merchant, running for just 12 episodes plus a two-part Christmas special. Its mockumentary style influenced numerous subsequent shows.' },
  { id: 'mov-78', category: 'movies-tv', difficulty: 'medium', question: 'In the film The Silence of the Lambs, what is the name of the serial killer Clarice Starling is hunting?', answer: 'Buffalo Bill', options: ['Hannibal Lecter', 'Buffalo Bill', 'Red Dragon', 'The Tooth Fairy'], explanation: 'Buffalo Bill, whose real name is Jame Gumb, kidnaps women to create a "suit" from their skin. The film swept all five major Oscar categories — Best Picture, Director, Actor, Actress, and Screenplay.' },
  { id: 'mov-79', category: 'movies-tv', difficulty: 'medium', question: 'What year did Netflix begin streaming content?', answer: '2007', options: ['2005', '2007', '2009', '2010'], explanation: 'Netflix launched its streaming service in January 2007, having previously been a DVD-by-mail service since 1997. The company began producing original content with House of Cards in 2013.' },
  { id: 'mov-80', category: 'movies-tv', difficulty: 'medium', question: 'Which actor plays both Tyler Durden and the unnamed narrator in Fight Club?', answer: 'Brad Pitt and Edward Norton', options: ['Brad Pitt and Edward Norton', 'Brad Pitt and Matt Damon', 'Johnny Depp and Edward Norton', 'Brad Pitt and Jake Gyllenhaal'], explanation: 'Brad Pitt plays Tyler Durden while Edward Norton plays the unnamed narrator in David Fincher\'s 1999 film. The film was based on Chuck Palahniuk\'s 1996 novel of the same name.' },
  { id: 'mov-81', category: 'movies-tv', difficulty: 'medium', question: 'What Pixar film takes place primarily inside the mind of an 11-year-old girl?', answer: 'Inside Out', options: ['Soul', 'Inside Out', 'Coco', 'Turning Red'], explanation: 'Inside Out (2015) personifies five core emotions: Joy, Sadness, Fear, Anger, and Disgust. Director Pete Docter was inspired by observing changes in his own daughter\'s personality as she grew up.' },
  { id: 'mov-82', category: 'movies-tv', difficulty: 'medium', question: 'What 1960 film by Stanley Kubrick depicts a slave revolt in ancient Rome?', answer: 'Spartacus', options: ['Ben-Hur', 'Spartacus', 'Gladiator', 'Cleopatra'], explanation: 'Spartacus stars Kirk Douglas in the title role and features the famous "I am Spartacus!" scene. Kubrick was brought in as a replacement director at Douglas\'s request after the original director was fired.' },
  { id: 'mov-83', category: 'movies-tv', difficulty: 'medium', question: 'In Game of Thrones, what is the name of Daenerys Targaryen\'s largest dragon?', answer: 'Drogon', options: ['Rhaegal', 'Viserion', 'Drogon', 'Balerion'], explanation: 'Drogon was named after Daenerys\'s late husband Khal Drogo. The other two dragons, Rhaegal and Viserion, were named after her brothers Rhaegar and Viserys.' },
  { id: 'mov-84', category: 'movies-tv', difficulty: 'medium', question: 'What 2019 film became the first South Korean film to win the Academy Award for Best Picture?', answer: 'Parasite', options: ['Oldboy', 'Parasite', 'Burning', 'Memories of Murder'], explanation: 'Parasite, directed by Bong Joon-ho, won four Oscars including Best Picture and Best Director. It was the first non-English-language film to win Best Picture in the Academy\'s 92-year history.' },
  { id: 'mov-85', category: 'movies-tv', difficulty: 'medium', question: 'What technique, where the camera zooms in while the dolly moves backward (or vice versa), was famously used in Jaws and Vertigo?', answer: 'Dolly zoom', options: ['Dutch angle', 'Dolly zoom', 'Tracking shot', 'Whip pan'], explanation: 'The dolly zoom creates a disorienting visual effect where the background appears to change size relative to the subject. It is sometimes called the "Vertigo effect" or "Hitchcock zoom" after its prominent use in Vertigo (1958).' },
  { id: 'mov-86', category: 'movies-tv', difficulty: 'medium', question: 'Which TV show features the characters Tony, Silvio, Paulie, and Christopher?', answer: 'The Sopranos', options: ['Goodfellas', 'The Sopranos', 'Boardwalk Empire', 'The Wire'], explanation: 'The Sopranos ran for six seasons on HBO from 1999 to 2007. Its controversial final scene cutting to black mid-sentence sparked years of debate about what happened to Tony.' },
  { id: 'mov-87', category: 'movies-tv', difficulty: 'medium', question: 'What 1985 film features a teenager who accidentally travels back to 1955?', answer: 'Back to the Future', options: ['The Terminator', 'Back to the Future', 'Bill & Ted\'s Excellent Adventure', 'Peggy Sue Got Married'], explanation: 'Back to the Future starred Michael J. Fox as Marty McFly and was directed by Robert Zemeckis. Eric Stoltz was originally cast as Marty and filmed for several weeks before being replaced by Fox.' },
  { id: 'mov-88', category: 'movies-tv', difficulty: 'medium', question: 'In the movie Gladiator, what is the name of Russell Crowe\'s character?', answer: 'Maximus', options: ['Spartacus', 'Maximus', 'Commodus', 'Aurelius'], explanation: 'Maximus Decimus Meridius is a Roman general who becomes a gladiator after his family is murdered. The film won five Academy Awards in 2001 including Best Picture and Best Actor for Crowe.' },
  { id: 'mov-89', category: 'movies-tv', difficulty: 'medium', question: 'What horror film franchise features a doll named Annabelle?', answer: 'The Conjuring', options: ['Chucky', 'The Conjuring', 'Saw', 'Insidious'], explanation: 'Annabelle first appeared in The Conjuring (2013) before getting her own spinoff films. The real Annabelle doll is actually a Raggedy Ann doll, kept in a glass case at the Warren\'s Occult Museum.' },
  { id: 'mov-90', category: 'movies-tv', difficulty: 'hard', question: 'What film was the first to use the Steadicam extensively for moving shots?', answer: 'Bound for Glory', options: ['Rocky', 'Bound for Glory', 'The Shining', 'Halloween'], explanation: 'Bound for Glory (1976) was the first feature film to make extensive use of the Steadicam, invented by Garrett Brown. Brown then used it on Rocky the same year, which brought it more public attention.' },
  { id: 'mov-91', category: 'movies-tv', difficulty: 'hard', question: 'Which director has received the most Academy Award nominations for Best Director without winning?', answer: 'Alfred Hitchcock', options: ['Alfred Hitchcock', 'Stanley Kubrick', 'Robert Altman', 'Sidney Lumet'], explanation: 'Alfred Hitchcock was nominated five times for Best Director but never won. He received an honorary Irving G. Thalberg Memorial Award in 1968, giving one of the shortest acceptance speeches in Oscar history.' },
  { id: 'mov-92', category: 'movies-tv', difficulty: 'hard', question: 'What film soundtrack was the best-selling album in music history before Michael Jackson\'s Thriller?', answer: 'Saturday Night Fever', options: ['Grease', 'Saturday Night Fever', 'The Sound of Music', 'A Hard Day\'s Night'], explanation: 'The Saturday Night Fever soundtrack (1977), featuring the Bee Gees, sold over 40 million copies worldwide and held the record as the best-selling album in music history until Thriller surpassed it. It spent 24 weeks at #1 on the Billboard 200.' },
  { id: 'mov-93', category: 'movies-tv', difficulty: 'hard', question: 'In the TV show Lost, what are the recurring numbers that appear throughout the series?', answer: '4, 8, 15, 16, 23, 42', options: ['4, 8, 15, 16, 23, 42', '3, 7, 14, 21, 33, 48', '2, 6, 12, 18, 24, 36', '5, 10, 15, 20, 25, 50'], explanation: 'These numbers appear on the hatch, as Hurley\'s lottery numbers, and throughout the series. In the show\'s mythology, they correspond to Jacob\'s candidates for protector of the island.' },
  { id: 'mov-94', category: 'movies-tv', difficulty: 'hard', question: 'What was the first horror film to be nominated for the Academy Award for Best Picture?', answer: 'The Exorcist', options: ['Psycho', 'The Exorcist', 'Rosemary\'s Baby', 'Jaws'], explanation: 'The Exorcist (1973) was nominated for ten Academy Awards, winning two (Best Sound Mixing and Best Adapted Screenplay). It remains one of the highest-grossing horror films of all time when adjusted for inflation.' },
  { id: 'mov-95', category: 'movies-tv', difficulty: 'hard', question: 'What Akira Kurosawa film was the basis for the plot of Star Wars: A New Hope?', answer: 'The Hidden Fortress', options: ['Seven Samurai', 'The Hidden Fortress', 'Yojimbo', 'Rashomon'], explanation: 'George Lucas has acknowledged The Hidden Fortress (1958) as a major influence, particularly its storytelling from the perspective of two lowly characters (inspiring C-3PO and R2-D2). Kurosawa\'s influence extends throughout Lucas\'s work.' },
  { id: 'mov-96', category: 'movies-tv', difficulty: 'hard', question: 'Which film was the first to feature synchronized recorded dialogue throughout?', answer: 'The Jazz Singer', options: ['The Jazz Singer', 'Lights of New York', 'Sunrise', 'The Singing Fool'], explanation: 'The Jazz Singer (1927), starring Al Jolson, is considered the first feature-length "talkie," though it actually only has a few minutes of synchronized dialogue. Lights of New York (1928) was the first all-talking feature.' },
  { id: 'mov-97', category: 'movies-tv', difficulty: 'hard', question: 'What is the name of the fictional brand of cigarettes that appears in many Quentin Tarantino films?', answer: 'Red Apple', options: ['Lucky Strike', 'Red Apple', 'Morley', 'Laramie'], explanation: 'Red Apple cigarettes appear in Pulp Fiction, Kill Bill, The Hateful Eight, Once Upon a Time in Hollywood, and other Tarantino films. Morley is another fictional brand used across multiple Hollywood productions.' },
  { id: 'mov-98', category: 'movies-tv', difficulty: 'hard', question: 'Who was the first African American to win the Academy Award for Best Actor?', answer: 'Sidney Poitier', options: ['Denzel Washington', 'Sidney Poitier', 'Morgan Freeman', 'Jamie Foxx'], explanation: 'Sidney Poitier won Best Actor for Lilies of the Field in 1964. Hattie McDaniel was the first African American to win any Oscar, earning Best Supporting Actress for Gone with the Wind in 1940.' },
  { id: 'mov-99', category: 'movies-tv', difficulty: 'hard', question: 'In the TV show The Wire, what stick-up man becomes a cooperating witness and is known for his distinctive way of whistling?', answer: 'Omar Little', options: ['Avon Barksdale', 'Marlo Stanfield', 'Omar Little', 'Stringer Bell'], explanation: 'Omar Little, played by Michael K. Williams, whistles "The Farmer in the Dell" when approaching his targets. He robs drug dealers but has a strict moral code about not targeting civilians.' },
  { id: 'mov-100', category: 'movies-tv', difficulty: 'hard', question: 'What is the longest film ever to win the Academy Award for Best Picture?', answer: 'Gone with the Wind', options: ['Lawrence of Arabia', 'Gone with the Wind', 'Ben-Hur', 'The Lord of the Rings: The Return of the King'], explanation: 'Gone with the Wind (1939) runs approximately 3 hours and 58 minutes (238 minutes). It won eight competitive Academy Awards and two honorary ones.' },
  { id: 'mov-101', category: 'movies-tv', difficulty: 'hard', question: 'What 1927 Fritz Lang film depicted a futuristic dystopian city and is one of the most expensive silent films ever made?', answer: 'Metropolis', options: ['Nosferatu', 'Metropolis', 'The Cabinet of Dr. Caligari', 'M'], explanation: 'Metropolis cost roughly 5 million Reichsmarks, making it the most expensive film produced at that point. Its Art Deco-influenced visual design has influenced countless science fiction films.' },
  { id: 'mov-102', category: 'movies-tv', difficulty: 'hard', question: 'Which TV show had the most-watched non-Super Bowl broadcast in US television history as of its 1983 finale?', answer: 'M*A*S*H', options: ['Cheers', 'Seinfeld', 'M*A*S*H', 'Dallas'], explanation: 'The M*A*S*H finale "Goodbye, Farewell and Amen" drew 105.9 million viewers on February 28, 1983. This record for a scripted broadcast stood for decades.' },
  { id: 'mov-103', category: 'movies-tv', difficulty: 'hard', question: 'What technique did Alfred Hitchcock use in "Rope" (1948) to make the film appear as one continuous shot?', answer: 'Hidden cuts disguised by passing objects', options: ['Digital stitching', 'Hidden cuts disguised by passing objects', 'A single 80-minute take', 'Split-screen compositing'], explanation: 'Hitchcock hid his cuts by having the camera dolly into a character\'s back or dark object, creating the illusion of a single continuous take. The film was actually composed of 10 takes, each lasting up to 10 minutes (the maximum reel length).' },
  { id: 'mov-104', category: 'movies-tv', difficulty: 'hard', question: 'Which actor holds the record for the most Academy Award nominations without a win?', answer: 'Peter O\'Toole', options: ['Peter O\'Toole', 'Glenn Close', 'Amy Adams', 'Richard Burton'], explanation: 'Peter O\'Toole received eight Best Actor nominations without winning, from Lawrence of Arabia to Venus. He received an honorary Oscar in 2003 but initially tried to decline it, saying he was "still in the game."' },
  { id: 'mov-105', category: 'movies-tv', difficulty: 'hard', question: 'What TV show introduced the concept of the "bottle episode," where an entire episode takes place in one location on a low budget?', answer: 'None specifically introduced it, but the term was popularized by Friends', options: ['Star Trek', 'None specifically introduced it, but the term was popularized by Friends', 'The X-Files', 'Seinfeld'], explanation: 'While bottle episodes existed long before the term, it was popularized in reference to Friends and similar 1990s sitcoms. The practice dates back to early TV and radio when budget constraints forced shows to use minimal sets.' },
  { id: 'mov-106', category: 'movies-tv', difficulty: 'hard', question: 'In the Coen Brothers\' The Big Lebowski, what is The Dude\'s real first name?', answer: 'Jeffrey', options: ['Walter', 'Jeffrey', 'Donald', 'Theodore'], explanation: 'Jeffrey Lebowski, played by Jeff Bridges, is nicknamed "The Dude." The character was partly inspired by film producer Jeff Dowd, whom the Coen Brothers knew.' },
  { id: 'mov-107', category: 'movies-tv', difficulty: 'hard', question: 'What was the first anime film to win the Academy Award for Best Animated Feature?', answer: 'Spirited Away', options: ['Princess Mononoke', 'Spirited Away', 'My Neighbor Totoro', 'Howl\'s Moving Castle'], explanation: 'Spirited Away (2001), directed by Hayao Miyazaki, won the award at the 2003 ceremony. It held the record as the highest-grossing film in Japanese box office history for nearly two decades.' },
  { id: 'mov-108', category: 'movies-tv', difficulty: 'hard', question: 'Which Martin Scorsese film holds the record for the most uses of the F-word in a mainstream film at the time of its release?', answer: 'The Wolf of Wall Street', options: ['Goodfellas', 'Casino', 'The Wolf of Wall Street', 'The Departed'], explanation: 'The Wolf of Wall Street (2013) contains approximately 569 uses of the F-word. Previously, Casino held the record among Scorsese films. The all-time record for any film is held by Swearnet: The Movie.' },
  { id: 'mov-109', category: 'movies-tv', difficulty: 'hard', question: 'What is the MacGuffin in Hitchcock\'s North by Northwest?', answer: 'Government microfilm', options: ['A stolen necklace', 'Government microfilm', 'A secret formula', 'A code name for a spy'], explanation: 'The microfilm is the classic MacGuffin — an object that drives the plot but whose specific nature is largely irrelevant. Hitchcock himself coined the popular usage of the term "MacGuffin" to describe such plot devices.' },
  { id: 'mov-110', category: 'movies-tv', difficulty: 'hard', question: 'What was the first film to gross over $100 million at the US domestic box office?', answer: 'Jaws', options: ['Star Wars', 'Jaws', 'The Godfather', 'The Exorcist'], explanation: 'Jaws (1975) was the first film to earn $100 million domestically, establishing the concept of the summer blockbuster. Star Wars surpassed it two years later.' },
  { id: 'mov-111', category: 'movies-tv', difficulty: 'hard', question: 'In Twin Peaks, what is the famous question that drives the series pilot?', answer: 'Who killed Laura Palmer?', options: ['Who killed Laura Palmer?', 'Who is BOB?', 'What happened in the Black Lodge?', 'Where are the owls?'], explanation: '"Who killed Laura Palmer?" became a national sensation when Twin Peaks premiered in 1990. The show, created by David Lynch and Mark Frost, was groundbreaking for bringing art-house sensibilities to network television.' },
  { id: 'mov-112', category: 'movies-tv', difficulty: 'hard', question: 'What Italian film movement emerged after World War II, emphasizing everyday life and using non-professional actors?', answer: 'Italian Neorealism', options: ['Italian Neorealism', 'Italian Futurism', 'Commedia all\'italiana', 'Spaghetti Western'], explanation: 'Italian Neorealism featured directors like Roberto Rossellini, Vittorio De Sica, and Luchino Visconti. Key films include Bicycle Thieves (1948) and Rome, Open City (1945), which depicted post-war Italian life with raw authenticity.' },
  { id: 'mov-113', category: 'movies-tv', difficulty: 'hard', question: 'Which Stanley Kubrick film was pulled from UK distribution at the director\'s own request after receiving death threats?', answer: 'A Clockwork Orange', options: ['Lolita', 'A Clockwork Orange', 'Full Metal Jacket', 'Dr. Strangelove'], explanation: 'Kubrick withdrew A Clockwork Orange from UK cinemas in 1973 after receiving threats and amid claims the film inspired copycat violence. It was not legally available in the UK again until after his death in 1999.' },
  { id: 'mov-114', category: 'movies-tv', difficulty: 'hard', question: 'What was the first R-rated film to gross over $100 million domestically?', answer: 'Beverly Hills Cop', options: ['The Godfather', 'Beverly Hills Cop', 'The Exorcist', 'Terminator 2'], explanation: 'Beverly Hills Cop (1984), starring Eddie Murphy, earned over $234 million domestically. It launched Murphy to superstardom and became the highest-grossing film of 1984.' },
  { id: 'mov-115', category: 'movies-tv', difficulty: 'hard', question: 'Who was the youngest person to win the Academy Award for Best Director?', answer: 'Damien Chazelle', options: ['Steven Spielberg', 'Damien Chazelle', 'Orson Welles', 'John Singleton'], explanation: 'Damien Chazelle won Best Director for La La Land at age 32 at the 2017 ceremony. John Singleton holds the record for youngest nominee at 24, for Boyz n the Hood.' },
  { id: 'mov-116', category: 'movies-tv', difficulty: 'hard', question: 'In what David Lynch film does a character find a severed ear in a field?', answer: 'Blue Velvet', options: ['Eraserhead', 'Blue Velvet', 'Mulholland Drive', 'Lost Highway'], explanation: 'Blue Velvet (1986) stars Kyle MacLachlan as Jeffrey Beaumont, who discovers the ear and is drawn into a mystery. Dennis Hopper\'s performance as Frank Booth is considered one of the most terrifying villain portrayals in cinema.' },
  { id: 'mov-117', category: 'movies-tv', difficulty: 'hard', question: 'What 1982 sci-fi film was initially a box office disappointment but later became a cult classic, with seven different versions released?', answer: 'Blade Runner', options: ['The Thing', 'Blade Runner', 'Tron', 'E.T. the Extra-Terrestrial'], explanation: 'Blade Runner, directed by Ridley Scott, originally flopped against E.T. which opened the same month. Ridley Scott\'s "Final Cut" (2007) is generally considered the definitive version among the seven cuts.' },
  { id: 'mov-118', category: 'movies-tv', difficulty: 'hard', question: 'What TV show featured the fictional advertising agency Sterling Cooper?', answer: 'Mad Men', options: ['Mad Men', 'Bewitched', 'thirtysomething', 'Halt and Catch Fire'], explanation: 'Mad Men aired on AMC from 2007 to 2015 and starred Jon Hamm as Don Draper. The show revitalized interest in 1960s fashion and cocktail culture.' },
  { id: 'mov-119', category: 'movies-tv', difficulty: 'hard', question: 'Which film contains the longest single tracking shot in cinema history among major releases, clocking in at over 6 minutes on the beach of Dunkirk?', answer: 'Atonement', options: ['1917', 'Atonement', 'Children of Men', 'Birdman'], explanation: 'The famous Dunkirk beach tracking shot in Atonement (2007) runs about 5 minutes and 30 seconds, showcasing the chaos of the evacuation. While longer shots exist in other films, this remains one of the most celebrated.' },
  { id: 'mov-120', category: 'movies-tv', difficulty: 'hard', question: 'What Orson Welles technique in Citizen Kane, using deep focus cinematography, was groundbreaking because it allowed what?', answer: 'Both foreground and background to be in sharp focus simultaneously', options: ['Shooting in complete darkness', 'Both foreground and background to be in sharp focus simultaneously', 'Filming in continuous motion without cuts', 'Superimposing two images on screen'], explanation: 'Cinematographer Gregg Toland used deep focus extensively in Citizen Kane (1941), allowing complex staging in depth. This technique let Welles tell stories through spatial relationships rather than relying on editing.' },
  { id: 'mov-121', category: 'movies-tv', difficulty: 'hard', question: 'What was the original title of the TV show Breaking Bad during its development?', answer: 'It was always called Breaking Bad', options: ['The Cook', 'It was always called Breaking Bad', 'Crystal Blue', 'Heisenberg'], explanation: 'Vince Gilligan pitched the show with the title Breaking Bad, a Southern slang term meaning "to turn to a life of crime." Gilligan, raised in Virginia, was familiar with the expression from his youth.' },
  { id: 'mov-122', category: 'movies-tv', difficulty: 'hard', question: 'Which film composer has won the most Academy Awards?', answer: 'Alan Menken', options: ['John Williams', 'Alan Menken', 'Hans Zimmer', 'Ennio Morricone'], explanation: 'Alan Menken has won eight Academy Awards for his work on Disney films including The Little Mermaid, Beauty and the Beast, Aladdin, and Pocahontas. John Williams has five wins from 54 nominations.' },
  { id: 'mov-123', category: 'movies-tv', difficulty: 'hard', question: 'What was the first streaming-original film to be nominated for the Academy Award for Best Picture?', answer: 'Roma', options: ['The Irishman', 'Roma', 'Marriage Story', 'Manchester by the Sea'], explanation: 'Roma (2018), directed by Alfonso Cuaron and distributed by Netflix, was nominated for ten Oscars and won three, including Best Director. It sparked debate about streaming films\' eligibility for theatrical awards.' },
  { id: 'mov-124', category: 'movies-tv', difficulty: 'hard', question: 'In the Coen Brothers\' Fargo, what is the name of the pregnant police chief investigating the murders?', answer: 'Marge Gunderson', options: ['Marge Gunderson', 'Brenda Johnson', 'Helen Gamble', 'Annie Savoy'], explanation: 'Frances McDormand won the Academy Award for Best Actress for her portrayal of Marge Gunderson. Her Minnesota accent and polite demeanor became iconic, and the character later inspired the Fargo TV series.' },
  { id: 'mov-125', category: 'movies-tv', difficulty: 'hard', question: 'What cinematic technique, named after a Soviet filmmaker, describes the editing principle that meaning is created by juxtaposing two different shots?', answer: 'Kuleshov Effect', options: ['Eisenstein Montage', 'Kuleshov Effect', 'Vertov Method', 'Pudovkin Principle'], explanation: 'The Kuleshov Effect, demonstrated by Lev Kuleshov in the 1910s-1920s, showed that audiences derive meaning from the interaction of sequential shots. In his experiment, the same expressionless face was perceived differently depending on the image paired with it.' },
]
